#!/bin/bash
# vendor_orangecheck.sh : orangecheck's sign-in code, from its published
# packages, into the site (2026-10-23; the button and Connect, 2026-10-24).
#
#   web/oc-button.mjs     @orangecheck/me-client's dist/button.mjs, less its
#                         source map's address: enhanceSignInButton, which
#                         makes our own button orangecheck's (its mark, its
#                         busy state, its window opened from the click), and
#                         OUTCOME_COPY, the words for how the window ended.
#                         It has no imports, so it is served from our own
#                         origin, as every page runs under script-src 'self'.
#   web/oc-button.css     dist/button.css: the mark's size and a 44 px
#                         target, at zero specificity, so site.css wins.
#   web/oc-connect-consent.mjs
#                         dist/connect-consent.mjs: the Connect box's words,
#                         CONNECT_CONSENT_LABEL and CONNECT_CONSENT_BLURB,
#                         exactly as orangecheck gives them.
#   api/_orangecheck.js   me-client's server checks (checkOcToken, which
#                         tells a token that is no good from a key set that
#                         cannot be read, bondMeets, and mergedHandles and
#                         matchMergedUser, which follow an orangecheck
#                         account merge), its Connect calls (connectProvision,
#                         connectDelete), and auth-core's
#                         integratorRevocationCheck (and its cache's reset,
#                         for tools/web/orangecheck_check.mjs), bundled into
#                         one file with jose, which they use.
#                         api/ has no node_modules: tools/deploy.sh copies
#                         every api/_*.js beside each route, and this is one.
#   assets/ui/orangecheck-mark-mono-white.svg
#                         @orangecheck/mark's mono mark in white, the icon on
#                         the app's Sign in with orangecheck (src/ui/
#                         sign_in_form.gd), whose words are light on dark.
#
# The versions are pinned here and written into each file's first line, so
# a change of version is a diff someone reads. Run it again to upgrade.
set -euo pipefail
ME=0.50.0
CORE=2.18.0
MARK=0.3.0
ESBUILD=0.24.2
R=$(cd "$(dirname "$0")/../.." && pwd)
W=$(mktemp -d "${TMPDIR:-/tmp}/vendor_orangecheck.XXXXXX")
trap 'rm -rf "$W"' EXIT
cd "$W"
npm init -y >/dev/null
npm install --ignore-scripts --no-audit --no-fund --silent \
  "@orangecheck/me-client@$ME" "@orangecheck/auth-core@$CORE" "@orangecheck/mark@$MARK" "esbuild@$ESBUILD"
cat > entry.mjs <<'EOF'
export { bondMeets, checkOcToken, connectDelete, connectProvision, exchangeNativeCode, matchMergedUser, mergedHandles } from "@orangecheck/me-client/server";
export { _resetJwksCachesForTests, integratorRevocationCheck } from "@orangecheck/auth-core";
EOF
./node_modules/.bin/esbuild entry.mjs --bundle --format=esm --platform=node --target=node22 \
  --external:hono --external:express --log-level=warning \
  --banner:js="// Generated by tools/web/vendor_orangecheck.sh from @orangecheck/me-client@$ME and @orangecheck/auth-core@$CORE. Do not edit." \
  --outfile="$R/api/_orangecheck.js"
# Each without its source map's address: the map is not served, and a page
# asking for it would be a 404 in every console that opens.
D=node_modules/@orangecheck/me-client/dist
for pair in button.mjs:oc-button.mjs button.css:oc-button.css connect-consent.mjs:oc-connect-consent.mjs; do
  from="${pair%%:*}"
  to="${pair##*:}"
  case "$to" in
    *.css) note="/* Generated by tools/web/vendor_orangecheck.sh from @orangecheck/me-client@$ME dist/$from. Do not edit. */" ;;
    *) note="// Generated by tools/web/vendor_orangecheck.sh from @orangecheck/me-client@$ME dist/$from. Do not edit." ;;
  esac
  { echo "$note"; grep -v 'sourceMappingURL=' "$D/$from"; } > "$R/web/$to"
done
cp node_modules/@orangecheck/mark/assets/svg/orangecheck-mark-mono-white.svg "$R/assets/ui/orangecheck-mark-mono-white.svg"
echo "vendor_orangecheck: me-client $ME, auth-core $CORE, mark $MARK:"
wc -c "$R/api/_orangecheck.js" "$R/web/oc-button.mjs" "$R/web/oc-button.css" "$R/web/oc-connect-consent.mjs" \
  "$R/assets/ui/orangecheck-mark-mono-white.svg"
